<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class SupplierBankAccount extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','supplier_id','currency_id','bank_name','bank_country','bank_branch','account_holder_name','encrypted_account_number','encrypted_iban','encrypted_routing_identifier','masked_reference','account_type','is_default','verification_status','status','created_by','verified_by','verified_at','last_reviewed_at']; protected $casts=['encrypted_account_number'=>'encrypted','encrypted_iban'=>'encrypted','encrypted_routing_identifier'=>'encrypted','is_default'=>'boolean','verified_at'=>'datetime','last_reviewed_at'=>'datetime']; public function supplier(){return $this->belongsTo(Supplier::class);} public function currency(){return $this->belongsTo(AccountingCurrency::class,'currency_id');} public function reviews(){return $this->hasMany(SupplierBankAccountReview::class,'supplier_bank_account_id');} public function safe():array{return ['id'=>$this->id,'company_id'=>$this->company_id,'supplier_id'=>$this->supplier_id,'bank_name'=>$this->bank_name,'bank_country'=>$this->bank_country,'bank_branch'=>$this->bank_branch,'account_holder_name'=>$this->account_holder_name,'masked_reference'=>$this->masked_reference,'account_type'=>$this->account_type,'is_default'=>$this->is_default,'verification_status'=>$this->verification_status,'status'=>$this->status,'currency'=>$this->currency?->only(['id','code']),'verified_at'=>$this->verified_at];} }
